251		buf := bytes.NewBuffer(make([]byte, 0, count*2))
252	
253		for i := 0; i < count; i++ {
254			t := float64(i) / sampleRate
255			amp := 1.0
256			if decay > 0 {
257				amp = math.Exp(-decay * t)
258			}
259	
260			phase := 2 * math.Pi * freq * t
261			var v float64
262			switch wave {
263			case waveSaw:
264				saw := 2 * (t*freq - math.Floor(0.5+t*freq))
265				v = saw
266			default:
