268					v = 1
269				} else {
270					v = -1
271				}
272			}
273	
274			sample := int16(v * volume * amp * math.MaxInt16)
275			_ = binary.Write(buf, binary.LittleEndian, sample)
276		}
277	
278		return buf.Bytes()
279	}
